const mensaje = $input.item.json.message;

if (!mensaje) {
  return { json: { chatId: '', sessionKey: '', inputText: '', skip: true, tipo: 'vacio' } };
}

const chatId = String(mensaje.chat.id);
const sessionKey = chatId;

// Texto normal
if (mensaje.text) {
  return { json: { chatId, sessionKey, inputText: mensaje.text.trim(), skip: false, tipo: 'texto' } };
}

// Nota de voz
if (mensaje.voice) {
  return { json: { chatId, sessionKey, inputText: '', fileId: mensaje.voice.file_id, skip: false, tipo: 'audio' } };
}

// Audio file
if (mensaje.audio) {
  return { json: { chatId, sessionKey, inputText: '', fileId: mensaje.audio.file_id, skip: false, tipo: 'audio' } };
}

// Otro (foto, sticker, etc.)
return { json: { chatId, sessionKey, inputText: '', skip: true, tipo: 'otro' } };

// Transcribe audio de Telegram usando Whisper (OpenAI)
// REEMPLAZA los tokens antes de activar
const BOT_TOKEN = $env.TELEGRAM_BOT_MANUAL_TOKEN;
const OPENAI_API_KEY = $env.OPENAI_API_KEY;

const fileId = $json.fileId;
const chatId = $json.chatId;
const sessionKey = $json.sessionKey;

try {
  // 1. Obtener ruta del archivo desde Telegram
  const fileInfo = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.telegram.org/bot${BOT_TOKEN}/getFile?file_id=${fileId}`,
    json: true
  });

  const filePath = fileInfo.result.file_path;
  const ext = filePath.split('.').pop() || 'ogg';

  // 2. Descargar el audio
  const audioBuffer = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.telegram.org/file/bot${BOT_TOKEN}/${filePath}`,
    encoding: null
  });

  // 3. Construir multipart form data para Whisper
  const boundary = 'boundary' + Date.now();
  const CRLF = '\r\n';
  const headerPart = `--${boundary}${CRLF}Content-Disposition: form-data; name="model"${CRLF}${CRLF}whisper-1${CRLF}--${boundary}${CRLF}Content-Disposition: form-data; name="file"; filename="audio.${ext}"${CRLF}Content-Type: audio/ogg${CRLF}${CRLF}`;
  const footerPart = `${CRLF}--${boundary}--${CRLF}`;

  const formBody = Buffer.concat([
    Buffer.from(headerPart, 'utf8'),
    Buffer.from(audioBuffer),
    Buffer.from(footerPart, 'utf8')
  ]);

  // 4. Enviar a Whisper
  const result = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.openai.com/v1/audio/transcriptions',
    headers: {
      'Authorization': `Bearer ${OPENAI_API_KEY}`,
      'Content-Type': `multipart/form-data; boundary=${boundary}`
    },
    body: formBody,
    json: true
  });

  return { json: { chatId, sessionKey, inputText: result.text || '[audio sin texto]' } };

} catch (error) {
  // Si falla la transcripción, pedir que escriba en texto
  return { json: { chatId, sessionKey, inputText: '[El audio no pudo transcribirse. El profesor envió una nota de voz — pídele que escriba su pregunta como texto.]' } };
}

const BASE_URL = $env.DASHBOARD_URL;
const API_SECRET = $env.TELEGRAM_API_SECRET;

const chatId = String($('Telegram Trigger (Manual)').item.json.message.chat.id);

try {
  const result = await this.helpers.httpRequest({
    method: 'POST',
    url: `${BASE_URL}/api/telegram/buscar-alumno`,
    headers: { 'x-api-key': API_SECRET, 'Content-Type': 'application/json' },
    body: { chatId, nombre: 'verificacion' },
    json: true
  });

  if (!result.ok && result.codigo === 'TELEGRAM_CHAT_NO_ENCONTRADO') {
    return JSON.stringify({ autenticado: false });
  }
  return JSON.stringify({ autenticado: true });
} catch (error) {
  return JSON.stringify({ autenticado: false, error: error.message });
}

